.dbconfig defensive off
BEGIN;
PRAGMA writable_schema = on;
PRAGMA foreign_keys = off;
PRAGMA encoding = 'UTF-8';
PRAGMA page_size = '4096';
PRAGMA auto_vacuum = '0';
PRAGMA user_version = '0';
PRAGMA application_id = '0';
CREATE TABLE sqlite_sequence(name,seq);
CREATE TABLE settings (
    key TEXT PRIMARY KEY,
    value TEXT -- JSON string
);
CREATE TABLE sync_tokens (
    token TEXT PRIMARY KEY,
    terminalId TEXT NOT NULL,
    createdAt TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE connected_terminals (
    terminalId TEXT PRIMARY KEY,
    lastSeen TEXT,
    ip TEXT,
    deviceToken TEXT,
    status TEXT
);
CREATE TABLE roles (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    permissions TEXT, -- JSON array
    maxDiscountPercent REAL,
    isSystem INTEGER DEFAULT 0,
    zReportConfig TEXT -- JSON object
);
CREATE TABLE users (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    pin TEXT NOT NULL,
    role TEXT,
    roleId TEXT,
    photo TEXT,
    FOREIGN KEY (roleId) REFERENCES roles(id)
);
CREATE TABLE warehouses (
    id TEXT PRIMARY KEY,
    code TEXT UNIQUE NOT NULL,
    name TEXT NOT NULL,
    type TEXT,
    address TEXT,
    allowPosSale INTEGER DEFAULT 1,
    allowNegativeStock INTEGER DEFAULT 0,
    isMain INTEGER DEFAULT 0,
    storeId TEXT
);
CREATE TABLE customers (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    phone TEXT,
    email TEXT,
    taxId TEXT,
    address TEXT,
    notes TEXT,
    loyaltyPoints REAL DEFAULT 0,
    creditLimit REAL DEFAULT 0,
    currentDebt REAL DEFAULT 0,
    tier TEXT,
    createdAt TEXT,
    totalSpent REAL DEFAULT 0,
    lastVisit TEXT,
    tags TEXT, -- JSON array
    requiresFiscalInvoice INTEGER DEFAULT 0,
    prefersEmail INTEGER DEFAULT 0,
    isTaxExempt INTEGER DEFAULT 0,
    applyChainedTax INTEGER DEFAULT 0,
    addresses TEXT, -- JSON array
    creditDays INTEGER DEFAULT 0,
    defaultNcfType TEXT
);
CREATE TABLE products (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    price REAL NOT NULL,
    category TEXT,
    stock REAL DEFAULT 0,
    image TEXT,
    barcode TEXT,
    cost REAL,
    type TEXT,
    images TEXT, -- JSON array
    attributes TEXT, -- JSON array
    variants TEXT, -- JSON array
    tariffs TEXT, -- JSON array
    stockBalances TEXT, -- JSON object (Legacy support)
    activeInWarehouses TEXT, -- JSON array
    appliedTaxIds TEXT, -- JSON array
    minStock REAL,
    warehouseSettings TEXT, -- JSON object
    availableModifiers TEXT, -- JSON array
    description TEXT,
    departmentId TEXT,
    sectionId TEXT,
    familyId TEXT,
    subfamilyId TEXT,
    brandId TEXT,
    operationalFlags TEXT, -- JSON object
    createdAt TEXT,
    updatedAt TEXT
, theoreticalCost REAL DEFAULT 0, recipeDetails TEXT, production_area_id TEXT, is_sellable INTEGER DEFAULT 1, measurementUnit TEXT, purchaseUnit TEXT, conversionFactor REAL DEFAULT 1, batchYield REAL DEFAULT 1, primarySupplierId TEXT);
CREATE TABLE product_stocks (
    id TEXT PRIMARY KEY, -- productId + '_' + warehouseId
    productId TEXT NOT NULL,
    warehouseId TEXT NOT NULL,
    quantity REAL DEFAULT 0,
    updatedAt TEXT,
    UNIQUE(productId, warehouseId),
    FOREIGN KEY (productId) REFERENCES products(id),
    FOREIGN KEY (warehouseId) REFERENCES warehouses(id)
);
CREATE TABLE inventory_ledger (
    id TEXT PRIMARY KEY,
    createdAt TEXT NOT NULL,
    warehouseId TEXT NOT NULL,
    productId TEXT NOT NULL,
    concept TEXT NOT NULL,
    documentRef TEXT,
    qtyIn REAL DEFAULT 0,
    qtyOut REAL DEFAULT 0,
    unitCost REAL DEFAULT 0,
    balanceQty REAL DEFAULT 0,
    balanceAvgCost REAL DEFAULT 0,
    terminalId TEXT,
    syncStatus TEXT DEFAULT 'PENDING',
    syncError TEXT,
    FOREIGN KEY (productId) REFERENCES products(id),
    FOREIGN KEY (warehouseId) REFERENCES warehouses(id)
);
CREATE TABLE transactions (
    id TEXT PRIMARY KEY,
    globalSequence INTEGER,
    displayId TEXT,
    documentType TEXT,
    seriesId TEXT,
    seriesNumber INTEGER,
    date TEXT NOT NULL,
    items TEXT NOT NULL, -- JSON array (CartItems)
    total REAL NOT NULL,
    payments TEXT, -- JSON array
    userId TEXT,
    userName TEXT,
    terminalId TEXT,
    status TEXT,
    customerId TEXT,
    customerName TEXT,
    customerSnapshot TEXT, -- JSON object
    taxAmount REAL DEFAULT 0,
    netAmount REAL DEFAULT 0,
    discountAmount REAL DEFAULT 0,
    isTaxIncluded INTEGER DEFAULT 0,
    ncf TEXT,
    ncfType TEXT,
    relatedTransactions TEXT, -- JSON array
    originalTransactionId TEXT,
    refundReason TEXT,
    syncStatus TEXT DEFAULT 'PENDING',
    syncError TEXT
, affectedInvoiceNumber TEXT, affectedNCF TEXT);
CREATE TABLE suppliers (
    id TEXT PRIMARY KEY,
    data TEXT -- JSON object
);
CREATE TABLE purchase_orders (
    id TEXT PRIMARY KEY,
    data TEXT -- JSON object
);
CREATE TABLE transfers (
    id TEXT PRIMARY KEY,
    data TEXT -- JSON object
);
CREATE TABLE z_reports (
    id TEXT PRIMARY KEY,
    openedAt TEXT,
    closedAt TEXT,
    terminalId TEXT,
    userId TEXT,
    userName TEXT,
    openingBalance REAL,
    closingBalance REAL,
    totalSales REAL,
    totalTaxes REAL,
    totalDiscounts REAL,
    totalCash REAL,
    totalCard REAL,
    totalTransfer REAL,
    totalOther REAL,
    status TEXT,
    syncStatus TEXT DEFAULT 'PENDING',
    syncError TEXT
, sequenceNumber TEXT, totalsByMethod TEXT, cashExpected TEXT, cashCounted TEXT, cashDiscrepancy TEXT, stats TEXT, transactionCount INTEGER, notes TEXT, baseCurrency TEXT, cashSales REAL, cashIn REAL, cashOut REAL);
CREATE TABLE cash_movements (
    id TEXT PRIMARY KEY,
    createdAt TEXT,
    type TEXT,
    amount REAL,
    concept TEXT,
    userId TEXT,
    userName TEXT,
    terminalId TEXT,
    zReportId TEXT,
    syncStatus TEXT DEFAULT 'PENDING',
    syncError TEXT
);
CREATE TABLE receptions (id TEXT PRIMARY KEY, data TEXT);
CREATE TABLE transaction_history (
                    id TEXT PRIMARY KEY,
                    globalSequence INTEGER,
                    displayId TEXT,
                    documentType TEXT,
                    seriesId TEXT,
                    seriesNumber INTEGER,
                    date TEXT NOT NULL,
                    items TEXT NOT NULL, -- JSON array
                    total REAL NOT NULL,
                    payments TEXT, -- JSON array
                    userId TEXT,
                    userName TEXT,
                    terminalId TEXT,
                    status TEXT,
                    customerId TEXT,
                    customerName TEXT,
                    customerSnapshot TEXT, -- JSON object
                    taxAmount REAL DEFAULT 0,
                    netAmount REAL DEFAULT 0,
                    discountAmount REAL DEFAULT 0,
                    isTaxIncluded INTEGER DEFAULT 0,
                    ncf TEXT,
                    ncfType TEXT,
                    relatedTransactions TEXT, -- JSON array
                    originalTransactionId TEXT,
                    refundReason TEXT,
                    affectedInvoiceNumber TEXT,
                    affectedNCF TEXT,
                    syncStatus TEXT DEFAULT 'PENDING',
                    syncError TEXT,
                    zReportId TEXT
                );
CREATE TABLE rooms (
                    id TEXT PRIMARY KEY,
                    name TEXT NOT NULL,
                    data TEXT
                , nombre TEXT NOT NULL DEFAULT 'Sala', consumo_minimo REAL DEFAULT 0, capacidad_personas INTEGER DEFAULT 0, cargo_servicio_pct REAL DEFAULT 0, orden INTEGER DEFAULT 0);
CREATE TABLE tables (
                    id TEXT PRIMARY KEY,
                    roomId TEXT NOT NULL,
                    name TEXT NOT NULL,
                    data TEXT,
                    status TEXT DEFAULT 'FREE', nombre TEXT, currentOrderId TEXT, currentOrderTotal REAL DEFAULT 0, timeSeated TEXT, waiterName TEXT, posX REAL DEFAULT 0, posY REAL DEFAULT 0, width REAL DEFAULT 80, height REAL DEFAULT 80, shape TEXT DEFAULT 'SQUARE', rotation REAL DEFAULT 0, waiterId TEXT,
                    FOREIGN KEY (roomId) REFERENCES rooms(id)
                );
CREATE TABLE terminals_rooms_visibility (
                    terminal_id TEXT NOT NULL,
                    room_id TEXT NOT NULL,
                    PRIMARY KEY (terminal_id, room_id),
                    FOREIGN KEY (room_id) REFERENCES rooms(id)
                );
CREATE TABLE parametros_operativos (
                    id TEXT PRIMARY KEY,
                    vertical_negocio TEXT DEFAULT 'RETAIL',
                    usa_mesas INTEGER DEFAULT 0,
                    pantalla_inicio TEXT DEFAULT 'VENTA_DIRECTA',
                    bloqueo_meseros INTEGER DEFAULT 0,
                    pedir_comensales INTEGER DEFAULT 1
                , usa_modulos_cocina INTEGER DEFAULT 0);
CREATE TABLE ordenes_detalles (id TEXT PRIMARY KEY, orden_id TEXT NOT NULL, producto_id TEXT NOT NULL, nombre TEXT NOT NULL, cantidad REAL NOT NULL, modificadores TEXT, estado_cocina TEXT DEFAULT 'PENDIENTE', hora_inicio_preparacion TEXT, hora_terminado TEXT, FOREIGN KEY (orden_id) REFERENCES transactions(id));
CREATE TABLE configuracion_kds (key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE production_areas (
    id TEXT PRIMARY KEY,
    nombre TEXT NOT NULL,
    modo_salida TEXT NOT NULL,
    target_terminal_id TEXT,
    printer_ip TEXT
);
CREATE TABLE sync_changes (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        collection TEXT NOT NULL,
        itemId TEXT NOT NULL,
        version INTEGER NOT NULL,
        op TEXT NOT NULL,
        payload TEXT,
        createdAt TEXT NOT NULL
    );
